const module = angular.module("irtech.netcity.school.settings",
	[
		"ngRoute", "ngSanitize", "ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap",
		"netcity.common.menu", "ngFileUpload", "ui.tree", "irtech.netcity.common", "irtech.netcity.ui-components"
	]);

require("./list/settingsListCtrl.js");
require("./edit/assignmentTypeWeightsCtrl.js");

import { SettingsRepository } from "./repository.js";

module
	.factory("settingsRepository", ($http, $dialogs, $alerts, $q) => new SettingsRepository($http, $dialogs, $alerts, $q))
	.config(($routeProvider, $locationProvider) => {
	$routeProvider
		.when("/list/", {
			templateUrl: "/static/dist/app/school/settings/list/template.html",
			controller: "SettingsListCtrl"
		})
		.otherwise({
			templateUrl: "/static/dist/app/school/settings/list/template.html",
			controller: "SettingsListCtrl"
		});
	$locationProvider.hashPrefix('');
	$locationProvider.html5Mode({
		enabled: true,
		requireBase: true
	});
});


