"use strict";

angular
	.module("irtech.netcity.school.settings")
	.controller("AssignmentTypeWeightsController", ($scope, $http, $document, $location, $appLoader, $uibModal, $uibModalInstance, $alerts, $q, $dialogs, $controller, settingsRepository, changeTracker) => {
		$scope.header = language.Generic.SchoolSettings.kAssignmentTypeWeightsSetup;

		$.extend($scope,
		{
			language: language,
			data: {
				assignmentTypes: [],
				assignmentTypesWeights: [],
				weights: []
			},
			state: {
				dataReady: false
			},
			messages: {
				from1Before100: language.Generic.Messages.kIntFromBefore.replace(/\{(\d+)\}/g, (match, index) => Array.prototype.slice.call([0, 100], 0)[index])
			}
		});

		$scope.cancel = () => {
			$uibModalInstance.dismiss("cancel");
		}

		$scope.save = (valid) => {
			if (valid) {
				settingsRepository.saveAssignmentTypesWeights(_.map($scope.data.weights, (item) => { return { assignmentTypeId: item.id, schoolId: +appContext.schoolId, weight: item.weight } })).then(() => {
					changeTracker.clearDataChanges($("div.modal.fade"));
					$alerts.success(language.Generic.Assignment.kAssignmentTypesWeightsWasSaved);
					$scope.cancel();
				});
			}
		}

		$scope.load = () => {
			$scope.state.dataReady = false;
			const getAssignmentTypes = settingsRepository.getAssignmentTypes().then((types) => {
				$scope.data.assignmentTypes = types;
			});
			const getAssignmentTypesWeights = settingsRepository.getAssignmentTypesWeights().then((weights) => {
				$scope.data.assignmentTypesWeights = weights;
			});
			let waits = [getAssignmentTypes, getAssignmentTypesWeights];
			$q.all(waits).then(() => {
				$scope.data.weights = _.chain($scope.data.assignmentTypes)
										.map(item => { return { id: item.id, name: item.name, weight: (_.find($scope.data.assignmentTypesWeights, (wt) => wt.assignmentTypeId === item.id)||{assignmentTypeId: item.id, weight: 10}).weight } })
										.sortBy(item => item.order)
										.toArray()
										.value();
				$scope.state.dataReady = true;
				$appLoader.hide();
			});

		}


		$scope.load();

		$controller("NetCityModalController", { $scope, $dialogs, $uibModalInstance, changeTracker });
	})
.directive('yrInteger', yrInteger);
function yrInteger() {
	return {
		restrict: 'A',
		link: function (scope, element, attrs) {

			element.on('keypress',
				function(event) {

					if (!isIntegerChar())
						event.preventDefault();

					function isIntegerChar() {
						return /[0-9]/.test(
							String.fromCharCode(event.which));
					}

				});

		}
	}
};




