"use strict";

angular
	.module("irtech.netcity.school.settings")
	.controller("SettingsListCtrl",
		($scope, $http, $document, $location, $appLoader, settingsRepository, $uibModal, $alerts, $q, $dialogs, changeTracker) => {

			$scope.$parent.page = {
				title: language.MenuFolders.kFNSchoolSettings
			};

			$.extend($scope,
			{
				language: language,
				data: {
					schoolSettings: {},
					grades: appContext.funcType === 1
						? [{ id: 0, name: language.Generic.Common.kGr0_s }, 
							{ id: 1, name: language.Generic.Common.kGr1_s }, 
							{ id: 2, name: language.Generic.Common.kGr2_s }, 
							{ id: 3, name: language.Generic.Common.kGr3_s }, 
							{ id: 4, name: language.Generic.Common.kGr4_s }, 
							{ id: 5, name: language.Generic.Common.kGr5_s }, 
							{ id: 6, name: language.Generic.Common.kGr6_s }, 
							{ id: 7, name: language.Generic.Common.kGr7_s }, 
							{ id: 8, name: language.Generic.Common.kGr8_s }]
						: [{ id: 0, name: "0" },
							{ id: 1, name: "1" },
							{ id: 2, name: "2" },
							{ id: 3, name: "3" },
							{ id: 4, name: "4" },
							{ id: 5, name: "5" },
							{ id: 6, name: "6" },
							{ id: 7, name: "7" },
							{ id: 8, name: "8" },
							{ id: 9, name: "9" },
							{ id: 10, name: "10" },
							{ id: 11, name: "11" },
							{ id: 12, name: "12" }],
					funcType: appContext.funcType,
					windowsAuth: false,
					oldMinMark: null,
					oldMaxMark: null
				},
				state: {
					dataReady: false
				}
			});

			$scope.load = () => {
				$scope.state.dataReady = false;
				const getSchoolSettings = settingsRepository.getSchoolSettings().then((settings) => {
					$scope.data.schoolSettings = settings;
					$scope.data.oldMinMark = $scope.data.schoolSettings.minMark;
					$scope.data.oldMaxMark = $scope.data.schoolSettings.maxMark;
				});
				const getWindowsAuth = settingsRepository.getWindowsAuth().then((windowsAuth) => {
					$scope.data.windowsAuth = windowsAuth;
				});
				let waits = [getSchoolSettings, getWindowsAuth];
				$q.all(waits).then(() => {
					$scope.state.dataReady = true;
					$appLoader.hide();
				});
			}

			$scope.saveExecute = () => {
				$appLoader.show();
				settingsRepository.saveSchoolSettings($scope.data.schoolSettings)
					.then((result) => {
						$appLoader.hide();
						$scope.data.schoolSettings = angular.copy(result);
						$scope.data.oldMinMark = $scope.data.schoolSettings.minMark;
						$scope.data.oldMaxMark = $scope.data.schoolSettings.maxMark;
						changeTracker.clearDataChanges();
						$alerts.success(language.Generic.SchoolSettings.kTitleSettings +
							language.Common.kOfSchool +
							language.Generic.SchoolSettings.kSuccessfulSaved);
					});
			}

			$scope.save = (valid) => {
				var juniorRange = { start: $scope.data.schoolSettings.juniorStepGrade.start, end: $scope.data.schoolSettings.juniorStepGrade.end }
				var middleRange = { start: $scope.data.schoolSettings.middleStepGrade.start, end: $scope.data.schoolSettings.middleStepGrade.end }
				var seniorRange = { start: $scope.data.schoolSettings.seniorStepGrade.start, end: $scope.data.schoolSettings.seniorStepGrade.end }
				if (valid
						&& $scope.isValidRange(juniorRange)
						&& $scope.isValidRange(middleRange)
						&& $scope.isValidRange(seniorRange)
						&& !$scope.isIntersectedGradesRanges()
						&& !$scope.isGradesRangesWrongOrder()
						&& !$scope.emptySpaceBetweenRanges()
					)
				{
					if ($scope.data.schoolSettings.minMark !== $scope.data.oldMinMark ||
						$scope.data.schoolSettings.maxMark !== $scope.data.oldMaxMark) {
						$dialogs
							.confirm(language.Generic.SetupSchoolUI.kConfirm, language.Generic.SchoolSettings.kConChangeMarkRange)
							.result
							.then(() => {
								$scope.saveExecute();
							});
					} else {
						$scope.saveExecute();
					}
				}
			}

			$scope.enabledMaxMark = () => {
				if (+settingsForm.MinMark.value && !$scope.data.schoolSettings.minMark) {
					$scope.data.schoolSettings.minMark = +settingsForm.MinMark.value;
				}
				if (+settingsForm.MaxMark.value && !$scope.data.schoolSettings.maxMark) {
					$scope.data.schoolSettings.maxMark = +settingsForm.MaxMark.value;
				}
				let minMark = Math.min($scope.data.schoolSettings.minMark || +settingsForm.MinMark.value, 99);
				let maxMark = $scope.data.schoolSettings.maxMark || +settingsForm.MaxMark.value;

				return minMark && minMark >= 1 && minMark < 100 && maxMark <= minMark
							? minMark + 1
							: (maxMark || 1) > 100
								? (minMark || 1) + 1
								: (maxMark || 1);
			}

			$scope.enabledMinMark = () => {
				if (+settingsForm.MaxMark.value && !$scope.data.schoolSettings.maxMark) {
					$scope.data.schoolSettings.maxMark = +settingsForm.MaxMark.value;
				}
				if (+settingsForm.MinMark.value && !$scope.data.schoolSettings.minMark) {
					$scope.data.schoolSettings.minMark = +settingsForm.MinMark.value;
				}
				let minMark = $scope.data.schoolSettings.minMark || +settingsForm.MinMark.value;
				let maxMark = Math.min($scope.data.schoolSettings.maxMark || +settingsForm.MaxMark.value, 100);
				return maxMark && maxMark > 1 && maxMark <= 100 && minMark >= maxMark
							? maxMark - 1
							: Math.min(minMark, 99) || (maxMark || 100) - 1;
			}

			$scope.isValidRange = (range) => {
				return range.end >= range.start;
			}

			$scope.isIntersectedOrInvalidRanges = (firstRange, secondRange) => {
				return !($scope.isValidRange(firstRange) && $scope.isValidRange(secondRange) && (firstRange.end < secondRange.start || secondRange.end < firstRange.start));
			}

			$scope.isIntersectedGradesRanges = () => {
				if ($scope.data.schoolSettings.juniorStepGrade && $scope.data.schoolSettings.middleStepGrade && $scope.data.schoolSettings.seniorStepGrade) {
					var juniorRange = { start: $scope.data.schoolSettings.juniorStepGrade.start, end: $scope.data.schoolSettings.juniorStepGrade.end }
					var middleRange = { start: $scope.data.schoolSettings.middleStepGrade.start, end: $scope.data.schoolSettings.middleStepGrade.end }
					var seniorRange = { start: $scope.data.schoolSettings.seniorStepGrade.start, end: $scope.data.schoolSettings.seniorStepGrade.end }
					return $scope.isValidRange(juniorRange)
							&& $scope.isValidRange(middleRange)
							&& $scope.isValidRange(seniorRange)
							&& ($scope.isIntersectedOrInvalidRanges(juniorRange, middleRange)
								|| $scope.isIntersectedOrInvalidRanges(juniorRange, seniorRange)
								|| $scope.isIntersectedOrInvalidRanges(seniorRange, middleRange));
				} else
				{ return false; }
			}

			$scope.emptySpaceBetweenRanges = () => {
				if ($scope.data.schoolSettings.juniorStepGrade &&
					$scope.data.schoolSettings.middleStepGrade &&
					$scope.data.schoolSettings.seniorStepGrade) {
					return $scope.data.schoolSettings.juniorStepGrade.end !== ($scope.data.schoolSettings.middleStepGrade.start - 1)
							|| $scope.data.schoolSettings.middleStepGrade.end !== ($scope.data.schoolSettings.seniorStepGrade.start - 1);
			} else {
					return false;
				}
			}

			$scope.isGradesRangesWrongOrder = () => {
				if ($scope.data.schoolSettings.juniorStepGrade && $scope.data.schoolSettings.middleStepGrade && $scope.data.schoolSettings.seniorStepGrade) {
					return $scope.data.schoolSettings.juniorStepGrade.start >= $scope.data.schoolSettings.middleStepGrade.start ||
								$scope.data.schoolSettings.juniorStepGrade.start >= $scope.data.schoolSettings.seniorStepGrade.start ||
								$scope.data.schoolSettings.middleStepGrade.start >= $scope.data.schoolSettings.seniorStepGrade.start;
				} else {
					return false;
				}
			}

			$scope.weights = () => {
				const modalInstance = $uibModal.open({
					templateUrl: "/static/dist/app/school/settings/edit/editAssignmentTypeWeightsTemplate.html",
					controller: 'AssignmentTypeWeightsController',
					size: "md",
					resolve: {
							}
				});

				modalInstance.rendered.then(() => {
				});

				modalInstance.result.then((options) => resolve(options));

			}

			$scope.load();
		}
	)


